node -e "
const pkg = require('./index.js');

// Test null/undefined guards for each function
const testCases = [
  ['capitalize', pkg.capitalize, [null]],
  ['capitalize', pkg.capitalize, [undefined]],
  ['slugify', pkg.slugify, [null]],
  ['slugify', pkg.slugify, [undefined]],
  ['clamp', pkg.clamp, [null, 0, 10]],
  ['clamp', pkg.clamp, [undefined, 0, 10]],
  ['sum', pkg.sum, [null]],
  ['sum', pkg.sum, [undefined]],
  ['isoDay', pkg.isoDay, [null]],
  ['isoDay', pkg.isoDay, [undefined]],
  ['checksum', pkg.checksum, [null]],
  ['checksum', pkg.checksum, [undefined]],
];

let passed = 0;
let failed = 0;

for (const [name, fn, args] of testCases) {
  try {
    fn(...args);
    console.log(\`❌ \${name}(\${args[0]}) did not throw\`);
    failed++;
  } catch (e) {
    if (e instanceof TypeError && e.message === \`\${name}: argument is required\`) {
      console.log(\`✓ \${name}(\${args[0]}) threw correctly\`);
      passed++;
    } else {
      console.log(\`❌ \${name}(\${args[0]}) threw wrong error: \${e.message}\`);
      failed++;
    }
  }
}

console.log(\`\nTests: \${passed} passed, \${failed} failed\`);
"

